package com.ashokmart.servlet;
import com.ashokmart.model.AdminOrderModels; import com.ashokmart.service.AdminOrderService; import com.ashokmart.util.DatabaseConnectionPool; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/orders") public final class AdminOrdersServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(AdminOrdersServlet.class); private static final java.util.Set<String> STATUSES=java.util.Set.of("PENDING","CONFIRMED","PROCESSING","SHIPPED","DELIVERED","CANCELLED"); public void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{var admin=AdminWebSupport.authenticatedAdmin(req,res);if(admin==null)return;try{String status=req.getParameter("status");if(status!=null){status=status.trim().toUpperCase();if(!STATUSES.contains(status))status=null;}int page=1;try{page=Math.max(1,Integer.parseInt(req.getParameter("page")));}catch(Exception ignored){}AdminOrderService svc=AdminWebSupport.adminOrderService(AdminWebSupport.pool(getServletContext()));req.setAttribute("orderPage",svc.getOrders(admin.userId(),new AdminOrderModels.Query(req.getParameter("search"),status,page,12)));req.setAttribute("selectedStatus",status);req.setAttribute("searchTerm",req.getParameter("search"));AdminWebSupport.moveFlash(req.getSession(false),req,"adminSuccess","adminError");req.getRequestDispatcher("/WEB-INF/views/admin-orders.jsp").forward(req,res);}catch(IllegalStateException e){LOG.error("Admin order listing failed",e);res.sendError(500,"Orders are temporarily unavailable.");}}}
